use serde::Serialize;

use crate::error::{Error, ErrorCode};

pub const DEFAULT_VISIBILITY_TIMEOUT: u32 = 30;
pub const DEFAULT_RETENTION_SECONDS: u32 = 345_600;

/// Where messages that were received too often are moved.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct DeadLetter {
    #[serde(rename = "DeadLetterQueue")]
    pub queue: String,
    #[serde(rename = "MaxReceiveCount")]
    pub max_receive_count: u32,
}

/// The full attribute set of a queue; serializes as the `Attributes` result member.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "PascalCase")]
pub struct Attributes {
    pub visibility_timeout: u32,
    pub delay_seconds: u32,
    pub retention_seconds: u32,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    #[serde(flatten)]
    pub dead_letter: Option<DeadLetter>,
}

/// The attributes a request names; the rest are absent. Value ranges are already
/// checked, the rules that relate attributes to each other are not.
#[derive(Debug, Default)]
pub struct AttributeSet {
    pub visibility_timeout: Option<u32>,
    pub delay_seconds: Option<u32>,
    pub retention_seconds: Option<u32>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    pub dead_letter_queue: Option<String>,
    pub max_receive_count: Option<u32>,
}

impl AttributeSet {
    /// Moves the dead-letter configuration out. Fails when only one of its two
    /// halves is present.
    pub fn take_dead_letter(&mut self) -> Result<Option<DeadLetter>, Error> {
        match (self.dead_letter_queue.take(), self.max_receive_count.take()) {
            (Some(queue), Some(max_receive_count)) => Ok(Some(DeadLetter {
                queue,
                max_receive_count,
            })),
            (None, None) => Ok(None),
            _ => Err(Error::new(
                ErrorCode::InvalidParameterValue,
                "DeadLetterQueue and MaxReceiveCount must be given together",
            )),
        }
    }
}

impl Attributes {
    /// The attributes of a new queue: given values, defaults for the rest.
    pub fn new(set: &AttributeSet, dead_letter: Option<DeadLetter>) -> Self {
        Self {
            visibility_timeout: set
                .visibility_timeout
                .unwrap_or(DEFAULT_VISIBILITY_TIMEOUT),
            delay_seconds: set.delay_seconds.unwrap_or(0),
            retention_seconds: set.retention_seconds.unwrap_or(DEFAULT_RETENTION_SECONDS),
            fifo: set.fifo.unwrap_or(false),
            content_based_deduplication: set.content_based_deduplication.unwrap_or(false),
            dead_letter,
        }
    }

    /// Overwrites the attributes that `set` names. `Fifo` is never changed.
    pub fn apply(&mut self, set: &AttributeSet, dead_letter: Option<DeadLetter>) {
        let AttributeSet {
            visibility_timeout,
            delay_seconds,
            retention_seconds,
            content_based_deduplication,
            ..
        } = *set;
        self.visibility_timeout = visibility_timeout.unwrap_or(self.visibility_timeout);
        self.delay_seconds = delay_seconds.unwrap_or(self.delay_seconds);
        self.retention_seconds = retention_seconds.unwrap_or(self.retention_seconds);
        self.content_based_deduplication =
            content_based_deduplication.unwrap_or(self.content_based_deduplication);
        if dead_letter.is_some() {
            self.dead_letter = dead_letter;
        }
    }
}
EOF
sed -i '' 's/^mod error;/mod attributes;\nmod error;\nmod names;/' src/lib.rs
cargo build -q 2>&1 | grep -E '^error' | head; cargo test -q 2>&1 | tail -4
git add src/names.rs src/attributes.rs src/lib.rs && git commit -qm "Add validated queue names, tokens and the attribute model

Names and group/dedup ids have a validity rule, so they are newtypes that can
only be built through parse. Attributes are split into the full set a queue
holds and the partial set a request names, because CreateQueue and
SetQueueAttributes apply different rules to the same partial input." && echo ok

