use crate::error::{Error, ErrorCode};

const FIFO_SUFFIX: &str = ".fifo";
const MAX_NAME_LEN: usize = 80;
const MAX_TOKEN_LEN: usize = 128;

fn is_name_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '-'
}

/// A queue name that satisfies the creation syntax of the spec.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct QueueName(String);

impl QueueName {
    pub fn parse(name: &str) -> Result<Self, Error> {
        let (stem, limit) = match name.strip_suffix(FIFO_SUFFIX) {
            Some(stem) => (stem, MAX_NAME_LEN - FIFO_SUFFIX.len()),
            None => (name, MAX_NAME_LEN),
        };
        let valid = !stem.is_empty()
            && stem.chars().count() <= limit
            && stem.chars().all(is_name_char);
        if valid {
            Ok(Self(name.to_owned()))
        } else {
            Err(Error::new(
                ErrorCode::QueueNameInvalid,
                format!("{name:?} is not a valid queue name"),
            ))
        }
    }

    pub fn is_fifo(&self) -> bool {
        self.0.ends_with(FIFO_SUFFIX)
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }

    pub fn into_string(self) -> String {
        self.0
    }
}

/// A group or deduplication id: 1 to 128 characters from `A-Z a-z 0-9 _ -`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Token(String);

impl Token {
    pub fn parse(value: &str) -> Option<Self> {
        let valid = !value.is_empty()
            && value.chars().count() <= MAX_TOKEN_LEN
            && value.chars().all(is_name_char);
        valid.then(|| Self(value.to_owned()))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

