use std::collections::{BTreeMap, HashMap, HashSet};

use serde::Serialize;

use crate::attributes::{Attributes, DeadLetter};
use crate::names::Token;

/// Why a message cannot be received right now.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Hold {
    Delayed { until: u64 },
    InFlight { until: u64, receipt: u64 },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Visible,
    Delayed,
    InFlight,
}

#[derive(Debug)]
pub struct Message {
    pub id: u64,
    pub body: String,
    pub sent_at: u64,
    pub receive_count: u32,
    pub first_received_at: Option<u64>,
    pub group: Option<Token>,
    pub sequence: Option<u64>,
    pub hold: Option<Hold>,
}

impl Message {
    pub fn state(&self, now: u64) -> State {
        match self.hold {
            Some(Hold::Delayed { until }) if now < until => State::Delayed,
            Some(Hold::InFlight { until, .. }) if now < until => State::InFlight,
            _ => State::Visible,
        }
    }
}

/// What a receive does with one examined message.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Action {
    Deliver,
    DeadLetter,
}

#[derive(Debug, Serialize, PartialEq, Eq)]
#[serde(rename_all = "PascalCase")]
pub struct Counts {
    pub visible: usize,
    pub in_flight: usize,
    pub delayed: usize,
}

/// The original of an accepted FIFO send, kept to answer duplicates.
#[derive(Debug, Clone, Copy)]
pub struct Accepted {
    pub at: u64,
    pub message_id: u64,
    pub sequence: Option<u64>,
}

#[derive(Debug)]
pub struct Queue {
    pub attributes: Attributes,
    /// Keyed by arrival number, so iteration is arrival order.
    messages: BTreeMap<u64, Message>,
    next_arrival: u64,
    next_sequence: u64,
    /// Receipt handle number to arrival number; entries may be stale, so every
    /// lookup is verified against the message.
    handles: HashMap<u64, u64>,
    pub dedup: HashMap<String, Accepted>,
}

impl Queue {
    pub fn new(attributes: Attributes) -> Self {
        Self {
            attributes,
            messages: BTreeMap::new(),
            next_arrival: 0,
            next_sequence: 1,
            handles: HashMap::new(),
            dedup: HashMap::new(),
        }
    }

    pub fn len(&self) -> usize {
        self.messages.len()
    }

    /// Removes messages past their retention. Must run whenever the clock or
    /// the retention changes.
    pub fn expire(&mut self, now: u64) {
        let retention = u64::from(self.attributes.retention_seconds);
        self.messages.retain(|_, m| now < m.sent_at + retention);
    }

    /// Appends a message and returns its sequence number on a FIFO queue. A
    /// message already past retention is counted but not kept.
    pub fn add(&mut self, now: u64, mut message: Message) -> Option<u64> {
        message.sequence = self.attributes.fifo.then(|| {
            let sequence = self.next_sequence;
            self.next_sequence += 1;
            sequence
        });
        let sequence = message.sequence;
        let retention = u64::from(self.attributes.retention_seconds);
        if now < message.sent_at + retention {
            self.messages.insert(self.next_arrival, message);
            self.next_arrival += 1;
        }
        sequence
    }

    pub fn purge(&mut self) {
        self.messages.clear();
        self.handles.clear();
    }

    pub fn counts(&self, now: u64) -> Counts {
        let mut counts = Counts {
            visible: 0,
            in_flight: 0,
            delayed: 0,
        };
        for message in self.messages.values() {
            match message.state(now) {
                State::Visible => counts.visible += 1,
                State::InFlight => counts.in_flight += 1,
                State::Delayed => counts.delayed += 1,
            }
        }
        counts
    }

    /// Decides, without changing anything, what a receive does. One pass in
    /// arrival order; `seen` holds the groups of earlier messages that stay.
    pub fn plan_receive(
        &self,
        now: u64,
        max_messages: usize,
        dead_letter: Option<&DeadLetter>,
    ) -> Vec<(u64, Action)> {
        let mut plan = Vec::new();
        let mut delivered = 0;
        let mut seen: HashSet<&str> = HashSet::new();
        for (&key, message) in &self.messages {
            if delivered == max_messages {
                break;
            }
            let group = message.group.as_ref().map(Token::as_str);
            let group_free = group.is_none_or(|g| !seen.contains(g));
            if group_free && message.state(now) == State::Visible {
                if dead_letter.is_some_and(|d| message.receive_count >= d.max_receive_count) {
                    plan.push((key, Action::DeadLetter));
                    continue;
                }
                plan.push((key, Action::Deliver));
                delivered += 1;
            }
            seen.extend(group);
        }
        plan
    }

    /// Delivers the message at `key`, which `plan_receive` found.
    pub fn deliver(&mut self, key: u64, now: u64, visibility: u32, receipt: u64) -> &Message {
        let message = self
            .messages
            .get_mut(&key)
            .expect("planned key is still in the queue");
        if let Some(Hold::InFlight { receipt: old, .. }) = message.hold {
            self.handles.remove(&old);
        }
        message.receive_count += 1;
        message.first_received_at.get_or_insert(now);
        message.hold = Some(Hold::InFlight {
            until: now + u64::from(visibility),
            receipt,
        });
        self.handles.insert(receipt, key);
        message
    }

    /// Removes the message at `key` for a dead-letter move, resetting what the
    /// move resets.
    pub fn take_for_dead_letter(&mut self, key: u64) -> Message {
        let mut message = self
            .remove(key)
            .expect("planned key is still in the queue");
        message.receive_count = 0;
        message.first_received_at = None;
        message.hold = None;
        message
    }

    pub fn remove(&mut self, key: u64) -> Option<Message> {
        let message = self.messages.remove(&key)?;
        if let Some(Hold::InFlight { receipt, .. }) = message.hold {
            self.handles.remove(&receipt);
        }
        Some(message)
    }

    /// The arrival number of the message whose latest handle is `receipt` and
    /// that is in flight now.
    pub fn find_in_flight(&self, receipt: u64, now: u64) -> Option<u64> {
        let key = *self.handles.get(&receipt)?;
        let message = self.messages.get(&key)?;
        let current = message.state(now) == State::InFlight
            && matches!(message.hold, Some(Hold::InFlight { receipt: r, .. }) if r == receipt);
        current.then_some(key)
    }

    /// Ends the visibility timeout of the in-flight message at `key` at `until`.
    pub fn set_in_flight_until(&mut self, key: u64, new_until: u64) {
        if let Some(Message {
            hold: Some(Hold::InFlight { until, .. }),
            ..
        }) = self.messages.get_mut(&key)
        {
            *until = new_until;
        }
    }
}
