            let queue = queue(q)?;
            let body = string("Body", b)?;
            if !(1..=1024).contains(&body.len()) {
                return Err(invalid("Body", "1 to 1024 bytes"));
            }
            Ok(Command::SendMessage {
                queue,
                body: body.to_owned(),
                delay: p.optional("DelaySeconds", |n, v| integer(n, v, 0..=900))?,
                group: p.optional("GroupId", token)?,
                deduplication: p.optional("DeduplicationId", token)?,
            })
        }
        "ReceiveMessage" => Ok(Command::ReceiveMessage {
            queue: queue(p.queue()?)?,
            max_messages: p
                .optional("MaxMessages", |n, v| integer(n, v, 1..=10))?
                .map_or(1, |n| n as usize),
            visibility: p.optional("VisibilityTimeout", |n, v| integer(n, v, 0..=43_200))?,
        }),
        "DeleteMessage" => {
            let (q, h) = (p.queue()?, p.required("ReceiptHandle")?);
