        }
        "ChangeMessageVisibility" => {
            let (q, h, v) = (p.queue()?, p.required("ReceiptHandle")?, p.required("VisibilityTimeout")?);
            Ok(Command::ChangeMessageVisibility {
                queue: queue(q)?,
                handle: string("ReceiptHandle", h)?.to_owned(),
                visibility: integer("VisibilityTimeout", v, 0..=43_200)?,
            })
        }
        other => Err(request_error(format!("unknown command {other:?}"))),
    }
}
