use std::collections::BTreeMap;

use serde::Serialize;

use crate::attributes::{Attributes, DeadLetter};
use crate::error::{Error, ErrorCode::*};
use crate::queue::{Accepted, Action, Counts, Hold, Message, Queue};
use crate::request::Command;

const MAX_QUEUES: usize = 1000;
const MAX_MESSAGES: usize = 100_000;
const DEDUP_WINDOW: u64 = 300;

#[derive(Debug, Serialize)]
#[serde(rename_all = "PascalCase")]
pub struct Received {
    message_id: String,
    receipt_handle: String,
    body: String,
    receive_count: u32,
    sent_at: u64,
    first_received_at: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    group_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    sequence_number: Option<u64>,
}

/// The result members of a successful command.
#[derive(Debug, Serialize)]
#[serde(untagged, rename_all_fields = "PascalCase")]
pub enum Reply {
    Done {},
    Attributes { attributes: Attributes, counts: Counts },
    QueueNames { queue_names: Vec<String> },
    Now { now: u64 },
    Sent {
        message_id: String,
        #[serde(skip_serializing_if = "Option::is_none")]
        sequence_number: Option<u64>,
    },
    Received { messages: Vec<Received> },
}

fn err(code: crate::error::ErrorCode, message: &str) -> Error {
    Error::new(code, message)
}

fn find<'a>(queues: &'a mut BTreeMap<String, Queue>, name: &str) -> Result<&'a mut Queue, Error> {
    queues
        .get_mut(name)
        .ok_or_else(|| Error::new(QueueDoesNotExist, format!("no queue named {name:?}")))
}

fn message_id(n: u64) -> String {
    format!("m-{n}")
}

/// The whole state of the process: the virtual clock, the queues and the id counters.
#[derive(Debug, Default)]
pub struct Service {
    now: u64,
    queues: BTreeMap<String, Queue>,
    messages_accepted: u64,
    deliveries: u64,
}

impl Service {
    pub fn execute(&mut self, command: Command) -> Result<Reply, Error> {
        match command {
            Command::CreateQueue { name, mut attributes } => {
                let fifo = attributes.fifo.unwrap_or(false);
                if name.is_fifo() != fifo {
                    return Err(err(QueueNameInvalid, "the .fifo suffix and Fifo must agree"));
                }
                if attributes.content_based_deduplication == Some(true) && !fifo {
                    return Err(err(InvalidParameterValue, "ContentBasedDeduplication needs Fifo"));
                }
                let dead_letter = attributes.take_dead_letter()?;
                let new = Attributes::new(&attributes, dead_letter);
                if let Some(existing) = self.queues.get(name.as_str()) {
                    return if existing.attributes == new {
                        Ok(Reply::Done {})
                    } else {
                        Err(err(QueueAlreadyExists, "the queue exists with other attributes"))
                    };
                }
                if let Some(d) = &new.dead_letter {
                    self.check_dead_letter_fifo(&d.queue, fifo)?;
                }
                if self.queues.len() >= MAX_QUEUES {
                    return Err(err(LimitExceeded, "1000 queues exist"));
                }
                self.queues.insert(name.into_string(), Queue::new(new));
                Ok(Reply::Done {})
            }
            Command::SetQueueAttributes { queue, mut attributes } => {
                let fifo = find(&mut self.queues, &queue)?.attributes.fifo;
                if attributes.fifo.is_some() {
                    return Err(err(UnsupportedOperation, "Fifo cannot change"));
                }
                if attributes.content_based_deduplication == Some(true) && !fifo {
                    return Err(err(InvalidParameterValue, "ContentBasedDeduplication needs Fifo"));
                }
                let dead_letter = attributes.take_dead_letter()?;
                if let Some(d) = &dead_letter {
                    if self.queues.get(&d.queue).is_none() {
                        return Err(err(QueueDoesNotExist, "the dead-letter queue does not exist"));
                    }
                    if d.queue == queue {
                        return Err(err(InvalidParameterValue, "a queue cannot be its own dead-letter queue"));
                    }
                    self.check_dead_letter_fifo(&d.queue, fifo)?;
                }
                let q = find(&mut self.queues, &queue)?;
                q.attributes.apply(&attributes, dead_letter);
                q.expire(self.now);
                Ok(Reply::Done {})
            }
            Command::GetQueueAttributes { queue } => {
                let q = find(&mut self.queues, &queue)?;
                Ok(Reply::Attributes { attributes: q.attributes.clone(), counts: q.counts(self.now) })
            }
            Command::ListQueues { prefix } => {
                let prefix = prefix.unwrap_or_default();
                let queue_names = self.queues.keys().filter(|n| n.starts_with(&prefix)).cloned().collect();
                Ok(Reply::QueueNames { queue_names })
            }
            Command::DeleteQueue { queue } => {
                find(&mut self.queues, &queue)?;
                self.queues.remove(&queue);
                for q in self.queues.values_mut() {
                    if q.attributes.dead_letter.as_ref().is_some_and(|d| d.queue == queue) {
                        q.attributes.dead_letter = None;
                    }
                }
                Ok(Reply::Done {})
            }
            Command::PurgeQueue { queue } => {
                find(&mut self.queues, &queue)?.purge();
                Ok(Reply::Done {})
            }
            Command::Tick { seconds } => {
                self.now += u64::from(seconds);
                for q in self.queues.values_mut() {
                    q.expire(self.now);
                }
                Ok(Reply::Now { now: self.now })
            }
            Command::SendMessage { queue, body, delay, group, deduplication } => {
                let now = self.now;
                let q = find(&mut self.queues, &queue)?;
                let fifo = q.attributes.fifo;
                if (!fifo && (group.is_some() || deduplication.is_some())) || (fifo && delay.is_some()) {
                    return Err(err(UnsupportedOperation, "parameter not supported by this queue type"));
                }
                if fifo && group.is_none() {
                    return Err(err(MissingParameter, "GroupId is required"));
                }
                if fifo && deduplication.is_none() && !q.attributes.content_based_deduplication {
                    return Err(err(MissingParameter, "DeduplicationId is required"));
                }
                let key = deduplication.as_ref().map_or(body.as_str(), |t| t.as_str());
                if fifo {
                    if let Some(a) = q.dedup.get(key).filter(|a| now - a.at < DEDUP_WINDOW) {
                        return Ok(Reply::Sent { message_id: message_id(a.message_id), sequence_number: a.sequence });
                    }
                }
